on conflict (estacion_id, producto_id, fecha) do update set inventario_inicial=excluded.inventario_inicial,ventas_galones=excluded.ventas_galones, recibos_galones=excluded.recibos_galones, inventario_teorico=excluded.inventario_teorico, inventario_final_real=excluded.inventario_final_real, fluctuacion_dia=excluded.fluctuacion_dia, fluctuacion_acumulada=excluded.fluctuacion_acumulada, fluctuacion_valor=excluded.fluctuacion_valor, estado=excluded.estado;